class udp2can_float(Structure):  # ctypes struct for receive
    _pack_ = 1  # Override Structure align
    _fields_ = [
        ("actuator_ID", c_uint8),
        ("verb", c_uint8),
        ("cmd", c_uint8),
        ("data", c_float),  # ctypes array
    ]


def float_data_through_udp(ip_addr, actuator_id, verb, cmd, data=0):
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.bind(("0.0.0.0", 12321))
    fcandata = udp2can_float()
    fcandata.verb = verb
    fcandata.cmd = cmd
    fcandata.actuator_ID = actuator_id
    fcandata.data = data
    s.settimeout(1)

    s.sendto(fcandata, (ip_addr, 24001))
    data, addr = s.recvfrom(1024)
    # print("Receiving: ", data.hex())
    payload_r = udp2can_float.from_buffer_copy(data)
    return [payload_r.actuator_ID, payload_r.data]


class udp2can_int(Structure):  # ctypes struct for receive
    _pack_ = 1  # Override Structure align
    _fields_ = [
        ("actuator_ID", c_uint8),
        ("verb", c_uint8),
        ("cmd", c_uint8),
        ("data", c_uint32),  # ctypes array
    ]


